import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.CFuv5BrO.js";const k=JSON.parse('{"title":"评测与结果","description":"Hearth 独立评测栈的入口、native 30 题结果、运行方法和不能被分数掩盖的边界。","frontmatter":{"title":"评测与结果","description":"Hearth 独立评测栈的入口、native 30 题结果、运行方法和不能被分数掩盖的边界。","outline":[2,3]},"headers":[],"relativePath":"evaluation/index.md","filePath":"evaluation/index.md","lastUpdated":1794450028000}'),l={name:"evaluation/index.md"};function d(o,e,r,h,n,c){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="评测与结果" tabindex="-1">评测与结果 <a class="header-anchor" href="#评测与结果" aria-label="Permalink to &quot;评测与结果&quot;">​</a></h1><p class="lead">评测回答的是“同一批真实任务，在不同执行器、重复次数和运行模式下，通过率、质量、耗时、Token 和审批次数发生了什么变化”，而不是用一个演示证明能力。</p><h2 id="评测栈在哪里" tabindex="-1">评测栈在哪里 <a class="header-anchor" href="#评测栈在哪里" aria-label="Permalink to &quot;评测栈在哪里&quot;">​</a></h2><p>评测代码已经拆分到独立仓库 <a href="https://github.com/hearthproject/hearth-eval" target="_blank" rel="noreferrer">hearthproject/hearth-eval</a>：</p><ul><li><code>apps/eval-server</code>：实验编排、SQLite、判分、复核、对比与 SPA 托管；</li><li><code>apps/eval-web</code>：总览、任务目录、实验、运行详情、复核、对比、活动流和系统状态；</li><li><code>packages/eval-core</code>：case 契约、目录加载、grader、评分与场景统计；</li><li><code>eval/cases</code>：60 个 case、输入与 golden；</li><li><code>scenario-runner</code>：30 个读取同级 Hearth 源码的白盒集成场景。</li></ul><p>主仓库只保留最小桥接：<code>POST /api/eval/tasks</code>、<code>POST /api/eval/judge</code>、<code>HEARTH_EVAL_INPUT_ROOT</code> 和 <code>.hearth/eval-artifacts/</code>。评测服务不复制 Hearth 的 Agent 执行链，也不跳过审批、沙箱和权限模型。</p><h2 id="native-30-题结果" tabindex="-1">Native 30 题结果 <a class="header-anchor" href="#native-30-题结果" aria-label="Permalink to &quot;Native 30 题结果&quot;">​</a></h2><p>2026-11-11 至 11-12，使用 30 个离线 case（8 个任务族均匀分布）、仅 <code>native</code> 执行器、重复 1 次、自动评分与自动重试开启、并发 4：</p><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:right;">结果</th></tr></thead><tbody><tr><td>最好完整单轮</td><td style="text-align:right;"><strong>18/30 通过（60%）</strong>，平均分 88.89</td></tr><tr><td>累计定向确认</td><td style="text-align:right;"><strong>19/30</strong> 个 case 曾达到 100 分</td></tr><tr><td>最近完整单轮</td><td style="text-align:right;">12/30 通过（40%），平均分 73.33</td></tr><tr><td>最终修复提交</td><td style="text-align:right;"><code>eb32ad5</code>，尚未做连续 30 题复测</td></tr></tbody></table><p>最好单轮实验为 <code>EXP-20261111145332-7a95ea</code>，最近完整实验为 <code>EXP-20261112003215-b1172b</code>。累计 19/30 来自不同轮次和定向重跑，不是一次连续实验，不能当作官方单轮成绩。</p><p>最近完整实验受到 provider 慢响应、评分 JSON 截断和任务超时影响，而且早于最后四个归一化修复，40% 不能直接等同于最终代码能力。CAL01、WEB01 等 case 还存在输入与评分 rubric 的语义歧义；T02、T11、WEB03 虽然得到 100 分，但因 <code>sampled</code> 标记未计为正式通过。</p><h2 id="报告" tabindex="-1">报告 <a class="header-anchor" href="#报告" aria-label="Permalink to &quot;报告&quot;">​</a></h2><ul><li><a href="/hearth-os/evaluation/native-30-final-report-2026-11-12.html">Native 30 任务最终评测报告（2026-11-12）</a> — 实验配置、完整实验汇总、逐任务结果、已实施修复、剩余风险与复测建议。</li><li><a href="/hearth-os/evaluation/native-30-baseline-2026-11-11.html">Native 30 任务基线评测（2026-11-11）</a> — 工具白名单缺失导致 0/30 的失效基线，以及桥接问题的定位过程。</li></ul><h2 id="如何复现" tabindex="-1">如何复现 <a class="header-anchor" href="#如何复现" aria-label="Permalink to &quot;如何复现&quot;">​</a></h2><p>主服务需要允许评测服务读取 case 输入：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># hearth-os\\.env</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HEARTH_EVAL_INPUT_ROOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D:\\App\\hearth</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">eval\\eval</span></span></code></pre></div><p>评测服务必须显式设置产物根，否则会因找不到已登记产物而错误判定 <code>BLOCKER_FAILED: exists</code>：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HEARTH_EVAL_ARTIFACT_ROOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;D:\\App\\hearth-os\\.hearth\\eval-artifacts&#39;</span></span></code></pre></div><p>启动后在评测控制台 <code>http://127.0.0.1:5174</code> 选择 30 个离线 case、<code>native</code> 执行器、重复 1 次、离线模式、自动评分和自动重试，再启动实验。重启服务后先通过 <code>GET /api/system</code> 确认 <code>artifactRoot</code>，再开始实验。</p><h2 id="分数不能替代什么" tabindex="-1">分数不能替代什么 <a class="header-anchor" href="#分数不能替代什么" aria-label="Permalink to &quot;分数不能替代什么&quot;">​</a></h2><ul><li>自动测试和场景通过只能证明控制面、评分逻辑和故障边界，不证明真实通过率。</li><li>离线 case 不覆盖真实邮件账户、真实日历、真实桌面设备和 <code>live-only</code> 任务。</li><li>模型评委不可用、评委冲突和抽样复核会进入 <code>needs_review</code>，不能静默算作通过。</li><li>最终提交 <code>eb32ad5</code> 还没有不中断的完整 30 题连续成绩；任何单轮数字都必须同时说明实验 ID、提交和运行条件。</li></ul>`,21)])])}const v=a(l,[["render",d]]);export{k as __pageData,v as default};
